PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS merchant(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS order_tbl(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchant(id),amount_paise INTEGER NOT NULL,created_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('created','paid','failed')));
CREATE TABLE IF NOT EXISTS payment(id TEXT PRIMARY KEY,order_id TEXT REFERENCES order_tbl(id),merchant_id TEXT NOT NULL REFERENCES merchant(id),amount_paise INTEGER NOT NULL,fee_paise INTEGER NOT NULL DEFAULT 0,tax_paise INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL CHECK(status IN ('captured','failed','refunded','partially_refunded')),method TEXT NOT NULL,created_at TEXT NOT NULL,settlement_id TEXT REFERENCES settlement(id));
CREATE TABLE IF NOT EXISTS settlement(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchant(id),amount_paise INTEGER NOT NULL,expected_amount_paise INTEGER NOT NULL,utr TEXT,status TEXT NOT NULL CHECK(status IN ('expected','settled','delayed')),expected_date TEXT NOT NULL,settled_date TEXT);
CREATE TABLE IF NOT EXISTS refund(id TEXT PRIMARY KEY,payment_id TEXT NOT NULL REFERENCES payment(id),merchant_id TEXT NOT NULL REFERENCES merchant(id),amount_paise INTEGER NOT NULL,created_at TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('processed','failed')));
CREATE TABLE IF NOT EXISTS ledger_entry(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchant(id),amount_paise INTEGER NOT NULL,description TEXT NOT NULL,value_date TEXT NOT NULL,reference TEXT,matched INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS expense(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchant(id),category TEXT NOT NULL,amount_paise INTEGER NOT NULL,due_date TEXT NOT NULL,recurring INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL CHECK(status IN ('scheduled','paid')));
CREATE TABLE IF NOT EXISTS reconciliation_run(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchant(id),started_at TEXT NOT NULL,completed_at TEXT,status TEXT NOT NULL CHECK(status IN ('running','completed','failed')),settlements_considered INTEGER,ledger_entries_considered INTEGER,active_cases_before INTEGER,active_cases_after INTEGER,new_cases INTEGER,resolved_cases INTEGER,error TEXT);
CREATE TABLE IF NOT EXISTS anomaly_detection_run(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchant(id),started_at TEXT NOT NULL,completed_at TEXT,status TEXT NOT NULL CHECK(status IN ('running','completed','failed')),days_scanned INTEGER,active_before INTEGER,active_after INTEGER,new_cases INTEGER,resolved_cases INTEGER,error TEXT);
CREATE TABLE IF NOT EXISTS reconciliation_match(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchant(id),case_key TEXT NOT NULL,settlement_id TEXT REFERENCES settlement(id),ledger_entry_id TEXT REFERENCES ledger_entry(id),status TEXT NOT NULL CHECK(status IN ('MATCHED','PARTIAL','DUPLICATE','MISSING_SETTLEMENT','UNKNOWN_CREDIT','UNKNOWN_DEBIT','REFUND_MISMATCH','AMOUNT_MISMATCH')),confidence REAL NOT NULL,evidence_json TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,last_run_id TEXT REFERENCES reconciliation_run(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(merchant_id,case_key));
CREATE TABLE IF NOT EXISTS financial_anomaly(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchant(id),case_key TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('RULE_BASED_ALERT','STATISTICAL_ANOMALY')),category TEXT NOT NULL,severity TEXT NOT NULL CHECK(severity IN ('low','medium','high')),evidence_json TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,last_run_id TEXT REFERENCES anomaly_detection_run(id),detected_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(merchant_id,case_key));
CREATE TABLE IF NOT EXISTS reconciliation_observation(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES reconciliation_run(id),case_id TEXT NOT NULL REFERENCES reconciliation_match(id),merchant_id TEXT NOT NULL REFERENCES merchant(id),case_key TEXT NOT NULL,status TEXT NOT NULL,confidence REAL NOT NULL,evidence_json TEXT NOT NULL,active INTEGER NOT NULL,observed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS anomaly_observation(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES anomaly_detection_run(id),case_id TEXT NOT NULL REFERENCES financial_anomaly(id),merchant_id TEXT NOT NULL REFERENCES merchant(id),case_key TEXT NOT NULL,kind TEXT NOT NULL,category TEXT NOT NULL,severity TEXT NOT NULL,evidence_json TEXT NOT NULL,active INTEGER NOT NULL,observed_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS approval_request(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchant(id),action_type TEXT NOT NULL,proposal_json TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('PROPOSED','AWAITING_APPROVAL','APPROVED','EXECUTING','SUCCEEDED','VERIFICATION_FAILED','FAILED','REJECTED')),attempt_number INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,decided_at TEXT,decided_by TEXT,result_json TEXT);
CREATE TABLE IF NOT EXISTS alert(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchant(id),approval_request_id TEXT NOT NULL UNIQUE REFERENCES approval_request(id),severity TEXT NOT NULL,message TEXT NOT NULL,evidence_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS finance_task(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchant(id),approval_request_id TEXT NOT NULL UNIQUE REFERENCES approval_request(id),task_type TEXT NOT NULL CHECK(task_type IN ('finance_task','schedule_review','investigation','payout_proposal','refund_recommendation')),title TEXT NOT NULL,detail_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reconciliation_report(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchant(id),approval_request_id TEXT NOT NULL UNIQUE REFERENCES approval_request(id),summary_json TEXT NOT NULL,generated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_event(id TEXT PRIMARY KEY,merchant_id TEXT NOT NULL REFERENCES merchant(id),actor TEXT NOT NULL,operation TEXT NOT NULL,inputs_json TEXT NOT NULL,evidence_json TEXT NOT NULL,decision TEXT,approval_state TEXT,result_json TEXT,error TEXT,created_at TEXT NOT NULL);
